using PointOfSale.Core.Analytics;

namespace PointOfSale.API.DTOs.Analytics;

/// <summary>
/// Request DTO for submitting an analytics event from the storefront.
/// 
/// SECURITY RULES:
/// - EventId: Generated by frontend for idempotency
/// - Type: Required, must be valid enum value
/// - OccurredAtUtc: From frontend, validated by backend (not future, not too old)
/// - Actor: CustomerId is IGNORED (resolved from JWT), SessionId accepted
/// - Context: IpAddress and UserAgent are IGNORED (captured server-side)
/// - Payload: Validated based on event type
/// </summary>
public class AnalyticsEventRequestDto
{
    /// <summary>
    /// Unique event ID for idempotency.
    /// Frontend should generate this (UUID v4) and retry with same ID on failure.
    /// If not provided, server will generate one (but retries won't be idempotent).
    /// </summary>
    public Guid? EventId { get; set; }

    /// <summary>
    /// The type of analytics event.
    /// Required. Must be a valid AnalyticsEventType value.
    /// </summary>
    public AnalyticsEventType Type { get; set; }

    /// <summary>
    /// When the event occurred (UTC).
    /// Optional. If not provided, server will use current time.
    /// Validated: Not in future, not older than 24 hours.
    /// </summary>
    public DateTime? OccurredAtUtc { get; set; }

    /// <summary>
    /// Actor information.
    /// CustomerId is IGNORED (resolved from JWT token).
    /// SessionId is used for guest tracking.
    /// </summary>
    public AnalyticsActorDto? Actor { get; set; }

    /// <summary>
    /// Context information.
    /// IpAddress and UserAgent are IGNORED (captured server-side).
    /// PageUrl is required.
    /// </summary>
    public AnalyticsContextDto? Context { get; set; }

    /// <summary>
    /// Payload information.
    /// Required fields depend on event type.
    /// </summary>
    public AnalyticsPayloadDto? Payload { get; set; }
}

/// <summary>
/// Actor DTO - WHO performed the event.
/// </summary>
public class AnalyticsActorDto
{
    /// <summary>
    /// Anonymous session ID for guest tracking.
    /// Required for guest users. Should be a UUID stored in localStorage.
    /// </summary>
    public string? SessionId { get; set; }
}

/// <summary>
/// Context DTO - WHERE and HOW the event occurred.
/// </summary>
public class AnalyticsContextDto
{
    /// <summary>
    /// The full URL of the page where the event occurred.
    /// Required.
    /// </summary>
    public string PageUrl { get; set; } = string.Empty;

    /// <summary>
    /// The referring URL (where the user came from).
    /// Optional.
    /// </summary>
    public string? Referrer { get; set; }

    /// <summary>
    /// User's preferred language (e.g., "en", "ar").
    /// Optional. Defaults to Accept-Language header.
    /// </summary>
    public string? Language { get; set; }

    /// <summary>
    /// Screen width in pixels.
    /// Optional. For responsive analytics.
    /// </summary>
    public int? ScreenWidth { get; set; }

    /// <summary>
    /// Screen height in pixels.
    /// Optional. For responsive analytics.
    /// </summary>
    public int? ScreenHeight { get; set; }
}

/// <summary>
/// Payload DTO - WHAT exactly happened.
/// </summary>
public class AnalyticsPayloadDto
{
    /// <summary>
    /// Product ID for product-related events.
    /// </summary>
    public Guid? ProductId { get; set; }

    /// <summary>
    /// Product variant ID for variant-specific events.
    /// </summary>
    public Guid? VariantId { get; set; }

    /// <summary>
    /// Order ID for purchase-related events.
    /// </summary>
    public Guid? OrderId { get; set; }

    /// <summary>
    /// Category ID for category-related events.
    /// </summary>
    public Guid? CategoryId { get; set; }

    /// <summary>
    /// Monetary value (product price, cart total, order total).
    /// </summary>
    public decimal? Value { get; set; }

    /// <summary>
    /// Quantity for cart events.
    /// </summary>
    public int? Quantity { get; set; }

    /// <summary>
    /// Search query for search events.
    /// </summary>
    public string? SearchQuery { get; set; }

    /// <summary>
    /// Applied filters for filter events.
    /// Key: filter name, Value: filter value.
    /// </summary>
    public Dictionary<string, string>? Filters { get; set; }

    /// <summary>
    /// Product name for display (optional).
    /// </summary>
    public string? ProductName { get; set; }

    /// <summary>
    /// Product SKU (optional).
    /// </summary>
    public string? ProductSku { get; set; }

    /// <summary>
    /// Extensible key-value pairs for additional data.
    /// </summary>
    public Dictionary<string, object>? Extra { get; set; }
}

/// <summary>
/// Response DTO for analytics event submission.
/// </summary>
public class AnalyticsEventResponseDto
{
    /// <summary>
    /// Whether the event was accepted.
    /// </summary>
    public bool Accepted { get; set; }

    /// <summary>
    /// The event ID (for tracking/debugging).
    /// </summary>
    public Guid EventId { get; set; }

    /// <summary>
    /// Error message if not accepted.
    /// </summary>
    public string? Error { get; set; }

    public static AnalyticsEventResponseDto Success(Guid eventId) => new()
    {
        Accepted = true,
        EventId = eventId
    };

    public static AnalyticsEventResponseDto Failure(string error) => new()
    {
        Accepted = false,
        Error = error
    };
}

/// <summary>
/// Request DTO for batch analytics event submission.
/// </summary>
public class AnalyticsEventBatchRequestDto
{
    /// <summary>
    /// List of events to submit.
    /// Maximum 50 events per batch.
    /// </summary>
    public List<AnalyticsEventRequestDto> Events { get; set; } = new();
}

/// <summary>
/// Response DTO for batch analytics event submission.
/// </summary>
public class AnalyticsEventBatchResponseDto
{
    /// <summary>
    /// Number of events accepted.
    /// </summary>
    public int Accepted { get; set; }

    /// <summary>
    /// Number of events rejected.
    /// </summary>
    public int Rejected { get; set; }

    /// <summary>
    /// Event IDs that were accepted.
    /// </summary>
    public List<Guid> AcceptedEventIds { get; set; } = new();

    /// <summary>
    /// Errors for rejected events.
    /// </summary>
    public List<AnalyticsEventErrorDto> Errors { get; set; } = new();
}

/// <summary>
/// Error details for a rejected event.
/// </summary>
public class AnalyticsEventErrorDto
{
    /// <summary>
    /// Index in the batch.
    /// </summary>
    public int Index { get; set; }

    /// <summary>
    /// Event ID if provided.
    /// </summary>
    public Guid? EventId { get; set; }

    /// <summary>
    /// Error message.
    /// </summary>
    public string Error { get; set; } = string.Empty;
}
